/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.scenario;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.consent.domain.TermsOfUseAcceptance;
import net.civeira.phylax.features.oauth.consent.domain.gateway.TermsOfUseConsentGateway;

@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class ScenarioTermsOfUseConsentGateway implements TermsOfUseConsentGateway {

  private static final TermsOfUseAcceptance DEFAULT_TERM =
      new TermsOfUseAcceptance("default-terms-id", "Terms and conditions");

  private Supplier<List<TermsOfUseAcceptance>> pendingSupplier = () -> List.of(DEFAULT_TERM);
  private final AtomicInteger acceptedCount = new AtomicInteger();
  private String lastTenant;
  private String lastUsername;
  private String lastConsentId;

  public void whenPending(Supplier<List<TermsOfUseAcceptance>> behavior) {
    this.pendingSupplier = behavior;
  }

  public void reset() {
    pendingSupplier = () -> List.of(DEFAULT_TERM);
    acceptedCount.set(0);
    lastTenant = null;
    lastUsername = null;
    lastConsentId = null;
  }

  public int getAcceptedCount() {
    return acceptedCount.get();
  }

  public String getLastTenant() {
    return lastTenant;
  }

  public String getLastUsername() {
    return lastUsername;
  }

  public String getLastConsentId() {
    return lastConsentId;
  }

  @Override
  public List<TermsOfUseAcceptance> getPendingConsent(String tenant, String username,
      List<String> audiences) {
    return pendingSupplier.get();
  }

  @Override
  public void storeAcceptedConsent(String tenant, String username, List<String> audiences,
      TermsOfUseAcceptance consent) {
    acceptedCount.incrementAndGet();
    lastTenant = tenant;
    lastUsername = username;
    lastConsentId = consent.id();
  }
}
